PROGRAM ST020_BLISTERMATNING
VAR
    steg         : INT := 0;
    trigAuto     : R_TRIG;
    trigHome     : R_TRIG;
    tmrUppehall  : TON;
    tmrKvittens  : TON;
    xVantarDone  : BOOL := FALSE;
    xTempfel     : BOOL := FALSE;
    xTidsfel     : BOOL := FALSE;
    xKravOmstart : BOOL := TRUE;
    xDriftsklar  : BOOL := FALSE;
END_VAR

(* EMG_OK lases bara. Logiken bar ingen sakerhetsfunktion; den ar forreglad AV
   nodstoppskretsen. *)
trigAuto(CLK := SYS_AUTO);

(* Indexet ar fardigt nar mataren har KOMMIT hem, alltsa pa hemlagesgivarens
   stigande flank. Givaren star hog aven medan mataren annu star kvar i
   hemlaget; lases nivan doms indexet klart i samma scan som det startas och
   verktyget gar ner mot ett band i rorelse. *)
trigHome(CLK := ST020_IDX_HOME);

(* Ett brutet nodstopp kraver en manuell kvittering innan maskinen far ga igen.
   Signalkartan bar ingen egen kvitteringsknapp, sa kvittensen ar
   automatlagesvaljaren: operatoren tar maskinen ur och tillbaka i AUTO. *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Arbetsfonstret 150 till 210 C. Under fonstret haller inte forslutningen,
   over det branns folien. Temperaturen ar en processstorhet och inget latchat
   fel: den kommer tillbaka av sig sjalv och da far cykeln fortsatta. *)
xTempfel := (ST020_SEA_TEMP < 150.0) OR (ST020_SEA_TEMP > 210.0);

(* Uteblir kvittensen fran forslutningen ar det INGET skal att indexera pa tid.
   Efter 3,0 s lyfts verktyget fran folien - en 150 till 210 C het stampel far
   inte sta kvar mot samma blister - och cykeln stannar tills nagon kvitterar. *)
xVantarDone := ST020_SEA_CLOSE AND NOT ST020_SEA_DONE;
tmrKvittens(IN := xVantarDone, PT := T#3s);
IF tmrKvittens.Q THEN
    xTidsfel := TRUE;
END_IF;

IF trigAuto.Q AND EMG_OK THEN
    xTidsfel := FALSE;
    xKravOmstart := FALSE;
END_IF;

(* Presstiden 0,90 s raknas fran att verktyget gick ner, inte fran indexstart. *)
tmrUppehall(IN := ST020_SEA_CLOSE, PT := T#900ms);

xDriftsklar := EMG_OK AND SYS_AUTO AND NOT xTidsfel AND NOT xKravOmstart;

IF NOT xDriftsklar THEN
    ST020_IDX_START := FALSE;
    ST020_SEA_CLOSE := FALSE;
    steg := 0;
ELSIF xTempfel THEN
    ST020_IDX_START := FALSE;
    ST020_SEA_CLOSE := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST020_SEA_CLOSE := FALSE;
            ST020_IDX_START := TRUE;
            steg := 1;
        1:
            IF trigHome.Q THEN
                ST020_IDX_START := FALSE;
                steg := 2;
            END_IF;
        2:
            ST020_SEA_CLOSE := TRUE;
            steg := 3;
        3:
            IF ST020_SEA_DONE AND tmrUppehall.Q THEN
                ST020_SEA_CLOSE := FALSE;
                steg := 4;
            END_IF;
        4:
            IF NOT ST020_SEA_DONE THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

